def is_connected(edges, n=9):
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    visited = [False] * n
    def dfs(node):
        visited[node] = True
        for nei in graph[node]:
            if not visited[nei]:
                dfs(nei)
    dfs(0)
    return all(visited)

edges = [(0,1),(0,8),(1,2),(1,5),(2,5),(2,6),(3,6),(4,6),(5,7)]
print(is_connected(edges))
